// Formats the n8n execution-error payload into a single Slack line block.
// Fires for ANY unhandled failure in a workflow that names this one as its
// Error Workflow — the catch-all so no failed run (and no order) is missed.
const p = $input.first().json || {};
const wf = p.workflow || {};
const ex = p.execution || {};
const err = ex.error || p.error || {};
const node = (err.node && (err.node.name || err.node)) || ex.lastNodeExecuted || 'unknown';

const lines = [
  '*Bagnetchon automation alert*',
  'severity: error',
  'stage:    workflow-crash',
  `workflow: ${wf.name || wf.id || 'unknown'}`,
  `node:     ${node}`,
  `error:    ${err.message || 'unknown error'}`,
];
if (ex.url) { lines.push(''); lines.push(`execution: ${ex.url}`); }

return [{ json: { text: lines.join('\n') } }];
